import { unzipSync } from "fflate";
// Generates the Ender IO sprite registry + CSS from one pinned upstream commit.
// Run: pnpm --filter @tennantite/textures sync:enderio-sprites
//
// The commit is pinned so the generated files are reproducible. `--check`
// re-renders and compares against the committed files.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const COMMIT = "672d750cd96bf2216fd0edf9e429558681d14191";
const ZIP_URL = `https://codeload.github.com/Team-EnderIO/EnderIO/zip/${COMMIT}`;
const ASSET_ROOT = "enderio/src/main/resources/assets/enderio/textures/gui/";

const ROOT = fileURLToPath(new URL("../", import.meta.url));
const OUT_TS = `${ROOT}src/enderio-sprites.generated.ts`;
const OUT_CSS = `${ROOT}css/enderio-sprites.generated.css`;
const OUT_TEXTURES = `${ROOT}css/enderio-textures.css`;

const check = process.argv.includes("--check");

function cssVar(name) {
  return `--mc-eio-${name.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}`;
}

async function download(url) {
  let lastError;
  for (let attempt = 1; attempt <= 4; attempt += 1) {
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status} ${response.statusText}`);
      }
      return new Uint8Array(await response.arrayBuffer());
    }
    catch (error) {
      lastError = error;
      if (attempt < 4) {
        await new Promise(resolve => setTimeout(resolve, attempt * 500));
      }
    }
  }
  throw new Error(`cannot download ${url}`, { cause: lastError });
}

function pngSize(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset);
  return { height: view.getUint32(20), width: view.getUint32(16) };
}

function sourceName(fullName) {
  const marker = fullName.indexOf(ASSET_ROOT);
  return marker === -1 ? null : fullName.slice(marker + ASSET_ROOT.length, -".png".length);
}

const zip = await download(ZIP_URL);
const files = unzipSync(zip, {
  filter(file) {
    const name = file.name;
    return Boolean(name.includes(ASSET_ROOT)) && Boolean(name.endsWith(".png")) && (sourceName(name) !== null);
  },
});

const sprites = new Map();
for (const [fullName, bytes] of Object.entries(files)) {
  const name = sourceName(fullName);
  if (name === null) {
    continue;
  }
  if (name !== "widgets" && !name.startsWith("screen/") && !name.startsWith("sprites/")) {
    continue;
  }
  sprites.set(name, bytes);
}

const entries = sprites.entries()
  .map(([name, bytes]) => {
    const { height, width } = pngSize(bytes);
    return {
      base64: Buffer.from(bytes).toString("base64"),
      cssVar: cssVar(name),
      height,
      name,
      sha256: createHash("sha256").update(bytes).digest("hex"),
      width,
    };
  })
  .toArray()
  .toSorted((a, b) => a.name.localeCompare(b.name));

if (entries.length < 145) {
  throw new Error(`expected at least 145 Ender IO sprites, got ${entries.length}`);
}

const metaLines = entries.map(entry => `  ${JSON.stringify(entry.name)}: {
    cssVar: ${JSON.stringify(entry.cssVar)},
    height: ${entry.height},
    sha256: ${JSON.stringify(entry.sha256)},
    width: ${entry.width},
  },`);

const ts = `// Generated by scripts/sync-enderio-sprites.mjs — DO NOT EDIT.
// Source: EnderIO ${COMMIT} (Unlicense, public domain).
// See LICENSE-ASSETS.md.
// Regenerate: pnpm --filter @tennantite/textures sync:enderio-sprites

export interface EioSpriteMeta {
  cssVar: string;
  height: number;
  sha256: string;
  width: number;
}

export const eioSpriteMeta = {
${metaLines.join("\n")}
} as const;

export type EioSpriteName = keyof typeof eioSpriteMeta;
`;

const cssLines = entries.map(
  entry => `  ${entry.cssVar}: url("data:image/png;base64,${entry.base64}");`,
);

const css = `/*
 * Generated by scripts/sync-enderio-sprites.mjs — DO NOT EDIT.
 * Source: EnderIO ${COMMIT} (Unlicense).
 * See LICENSE-ASSETS.md.
 */
:root {
${cssLines.join("\n")}
}
`;

const textures = `/*
 * Ender IO sprite layer. Import after the vanilla sprite CSS.
 * Generated data URIs live in enderio-sprites.generated.css.
 */
@import "./enderio-sprites.generated.css";

.mc-eio-sprite {
  background-repeat: no-repeat;
  image-rendering: pixelated;
}
`;

if (check) {
  let isStale = false;
  for (const [file, expected] of [
    [OUT_TS, ts],
    [OUT_CSS, css],
    [OUT_TEXTURES, textures],
  ]) {
    let actual = "";
    try {
      actual = readFileSync(file, "utf8");
    }
    catch {
      isStale = true;
      continue;
    }
    if (actual === expected) {
      continue;
    }
    isStale = true;
    console.error(`out of date: ${file}`);
  }
  if (isStale) {
    process.exit(1);
  }
  console.log(`Ender IO sprites up to date (${entries.length})`);
}
else {
  writeFileSync(OUT_TS, ts);
  writeFileSync(OUT_CSS, css);
  writeFileSync(OUT_TEXTURES, textures);
  console.log(`wrote ${entries.length} Ender IO sprites`);
}
